package edu.pitt.cs;

import com.pholser.junit.quickcheck.From;
import com.pholser.junit.quickcheck.Property;
import com.pholser.junit.quickcheck.runner.JUnitQuickcheck;
import org.junit.runner.RunWith;

import static org.junit.Assert.*;

@RunWith(JUnitQuickcheck.class)
public class CalculatorTest {

	/**
	 * <pre>
	 * Preconditions: s is an arbitrary string generated by QuickCheck's default String generator.
	 * Execution steps: Call Calculator.evaluate(s).
	 * Invariants: The call either returns normally or throws an IllegalArgumentException.
	 *             No other exception (e.g. StringIndexOutOfBoundsException) is ever thrown.
	 * </pre>
	 * 
	 * @param s A string generated by QuickCheck
	 */
	@Property(trials = 1000)
	public void testEvaluateRandomString(String s) {
		// System.out.println("testEvaluateRandomString s='" + s + "'");
		try {
			Calculator.evaluate(s);
		} catch (IllegalArgumentException e) {
			// Rejecting a malformed expression is the correct behavior.
		}
	}

	/**
	 * <pre>
	 * Preconditions: e is an expression tree generated by ExprGenerator.
	 * Execution steps: Call Calculator.evaluate(e.render()).
	 * Invariants: The return value is equal to e.value().
	 * </pre>
	 * 
	 * @param e An expression tree generated by ExprGenerator
	 */
	@Property(trials = 1000)
	public void testEvaluate(@From(ExprGenerator.class) Expr e) {
		// System.out.println("testEvaluate e='" + e + "'");
		assertEquals("Calculator.evaluate(\"" + e + "\")", e.value(), Calculator.evaluate(e.render()));
	}
}
